        emon.Port.Cells refs = emon.Port.NewCells();
        emon.Port.Cells cg = emon.Port.NewCells();
        Evidence.EpNew(epages, 1, 61200, 79200);
        // line 0: the text layer has a b c, OCR missed b. line 1: the text layer has d f, OCR also read e between them.
        XlTw(words, etext, feats, 1, 7200, 10000, 9600, 11200, 0, 0, 0, Model.SrText(), 0, emon.Testport.TextBlob("alpha"));
        XlTw(words, etext, feats, 1, 10200, 10000, 12600, 11200, 0, 0, 0, Model.SrText(), 0, emon.Testport.TextBlob("bravo"));
        XlTw(words, etext, feats, 1, 13200, 10000, 15600, 11200, 0, 0, 0, Model.SrText(), 0, emon.Testport.TextBlob("delta"));
        XlTw(words, etext, feats, 1, 7200, 14000, 9600, 15200, 0, 0, 1, Model.SrText(), 0, emon.Testport.TextBlob("echo"));
        XlTw(words, etext, feats, 1, 13200, 14000, 15600, 15200, 0, 0, 1, Model.SrText(), 0, emon.Testport.TextBlob("golf"));
        XlOw(owords, etext, feats, 1, 7200, 10000, 9600, 11200, 0, 0, 0, emon.Testport.TextBlob("alpha"));
        XlOw(owords, etext, feats, 1, 13200, 10000, 15600, 11200, 0, 0, 0, emon.Testport.TextBlob("delta"));
        XlOw(owords, etext, feats, 1, 7200, 14000, 9600, 15200, 0, 0, 0, emon.Testport.TextBlob("echo"));
        XlOw(owords, etext, feats, 1, 10200, 14000, 12600, 15200, 0, 0, 0, emon.Testport.TextBlob("foxtrot"));
        XlOw(owords, etext, feats, 1, 13200, 14000, 15600, 15200, 0, 0, 0, emon.Testport.TextBlob("golf"));
        emon.Testport.AssertEq(XlAlign(epages, words, owords, tlines, feats, etext, refs, cg, 1), 6, "alpha, bravo, delta, echo, golf, foxtrot");
        emon.Testport.AssertEq(Player.CgGet(cg, 1, Player.CgfFlags()), Player.PlgTextOnly(), "bravo: text-only");
        emon.Testport.AssertEq(Player.CgGet(cg, 1, Player.CgfOcount()), 0, "bravo: no OCR");
        emon.Testport.AssertEq(Player.CgGet(cg, 1, Player.CgfSim()), -1, "bravo: no similarity");
        emon.Testport.AssertEq(Player.CgGet(cg, 0, Player.CgfOcount()), 1, "alpha is matched");
        emon.Testport.AssertEq(Player.CgGet(cg, 2, Player.CgfOcount()), 1, "delta is matched");
        emon.Testport.AssertEq(Player.CgGet(cg, 5, Player.CgfFlags()), Player.PlgOcrOnly(), "foxtrot: OCR-only, and last (the OCR-only ones follow the text layer's)");
