        emon.Testport.AssertEq(Player.CgGet(cg, 5, Player.CgfSim()), -1, "foxtrot: no similarity");
        emon.Testport.AssertEq(Player.CgGet(cg, 4, Player.CgfOcount()), 1, "golf is matched");
        emon.Testport.AssertEq(Evidence.FeGet(feats, 1, Evidence.XtSimOcr()), -1, "bravo's column stays");
    }
