    [Xunit.Fact]
    public static void TestARightToLeftLineIsInLogicalOrder() {
        emon.Port.Cells epages = emon.Port.NewCells();
        emon.Port.Cells words = emon.Port.NewCells();
        emon.Port.Cells owords = emon.Port.NewCells();
        emon.Port.Cells tlines = emon.Port.NewCells();
        emon.Port.Cells feats = emon.Port.NewCells();
        emon.Port.Cells etext = emon.Port.NewCells();
        emon.Port.Cells refs = emon.Port.NewCells();
        emon.Port.Cells cg = emon.Port.NewCells();
        Evidence.EpNew(epages, 1, 61200, 79200);
        // the text layer in logical order, first word at the right (the baseline runs left to right, as the evidence has it)
        XlTw(words, etext, feats, 1, 20000, 10000, 23000, 11200, 0, 1, 0, Model.SrText(), 0, emon.Testport.TextBlob("first"));
        XlTw(words, etext, feats, 1, 16000, 10000, 19000, 11200, 0, 1, 0, Model.SrText(), 0, emon.Testport.TextBlob("second"));
        XlTw(words, etext, feats, 1, 12000, 10000, 15000, 11200, 0, 1, 0, Model.SrText(), 0, emon.Testport.TextBlob("third"));
        // OCR in VISUAL order, left to right, so only the reversal of a right-to-left line pairs them
        XlOw(owords, etext, feats, 1, 12000, 10000, 15000, 11200, 0, 1, 0, emon.Testport.TextBlob("third"));
        XlOw(owords, etext, feats, 1, 16000, 10000, 19000, 11200, 0, 1, 0, emon.Testport.TextBlob("second"));
        XlOw(owords, etext, feats, 1, 20000, 10000, 23000, 11200, 0, 1, 0, emon.Testport.TextBlob("first"));
        emon.Testport.AssertEq(XlAlign(epages, words, owords, tlines, feats, etext, refs, cg, 1), 3, "three groups");
        emon.Testport.AssertEq(Player.CgGet(cg, 0, Player.CgfSim()), 1000, "first is first");
        emon.Testport.AssertEq(Player.CgGet(cg, 1, Player.CgfSim()), 1000, "second is second");
        emon.Testport.AssertEq(Player.CgGet(cg, 2, Player.CgfSim()), 1000, "third is third");
        emon.Testport.AssertEq(XlRef(cg, refs, 0, Player.CgfOfirst(), 0), 2, "first is the last OCR word");
    }
