        XlOw(owords, etext, feats, 1, 11000, 10000, 14000, 11200, 0, 0, 0, emon.Testport.TextBlob("world"));
        XlOw(owords, etext, feats, 1, 20000, 10000, 24000, 11200, 0, 0, 0, emon.Testport.TextBlob("PAID"));
        XlOw(owords, etext, feats, 1, 7230, 10020, 10230, 11220, 0, 0, 4, emon.Testport.TextBlob("Hello"));
        XlOw(owords, etext, feats, 1, 11030, 10020, 14030, 11220, 0, 0, 4, emon.Testport.TextBlob("wor1d"));
        XlOw(owords, etext, feats, 1, 20030, 10020, 24030, 11220, 0, 0, 4, emon.Testport.TextBlob("PA1D"));
        emon.Testport.AssertEq(XlAlign(epages, words, owords, tlines, feats, etext, refs, cg, 1), 3, "three groups: Hello, world, the stamp");
        emon.Testport.AssertEq(Player.CgGet(cg, 0, Player.CgfOcount()), 2, "a group holds both runs' words");
        emon.Testport.AssertEq(Player.CgGet(cg, 1, Player.CgfOcount()), 2, "world as well");
        emon.Testport.AssertEq(Player.CgGet(cg, 1, Player.CgfSim()), 1000, "the group's similarity is the first run's");
        emon.Testport.AssertEq(Evidence.FeGet(feats, 1, Evidence.XtSimOcr()), 1000, "the text word's column 24 is the first run's");
        emon.Testport.AssertEq(Evidence.FeGet(feats, 1, Evidence.XtSimOcr2()), 800, "and its column 25 the second's");
        emon.Testport.AssertEq(Evidence.FeGet(feats, 6, Evidence.XoSimText()), 800, "the second run's word has its own");
        emon.Testport.AssertEq(Player.CgGet(cg, 2, Player.CgfFlags()), Player.PlgOcrOnly(), "the stamp is OCR-only");
        emon.Testport.AssertEq(Player.CgGet(cg, 2, Player.CgfOcount()), 2, "and both runs' readings of it are one group");
        emon.Testport.AssertEq(Player.CgGet(cg, 2, Player.CgfTcount()), 0, "without a text word");
    }
    [Xunit.Fact]
    public static void TestHiddenTextAndAnInvisibleWord() {
        emon.Port.Cells epages = emon.Port.NewCells();
        emon.Port.Cells words = emon.Port.NewCells();
        emon.Port.Cells owords = emon.Port.NewCells();
        emon.Port.Cells tlines = emon.Port.NewCells();
        emon.Port.Cells feats = emon.Port.NewCells();
        emon.Port.Cells etext = emon.Port.NewCells();
        emon.Port.Cells refs = emon.Port.NewCells();
        emon.Port.Cells cg = emon.Port.NewCells();
        Evidence.EpNew(epages, 1, 61200, 79200);
        // a visible word, a hidden-text word (an older OCR layer under a scan) and a word that is clipped away (vis 1)
        XlTw(words, etext, feats, 1, 7200, 10000, 10200, 11200, 0, 0, 0, Model.SrText(), 0, emon.Testport.TextBlob("seen"));
        XlTw(words, etext, feats, 1, 11000, 10000, 14000, 11200, 0, 0, 1, Model.SrHiddenText(), 0, emon.Testport.TextBlob("older"));
        XlTw(words, etext, feats, 1, 15000, 10000, 18000, 11200, 0, 0, 2, Model.SrText(), 1, emon.Testport.TextBlob("clip"));
        XlOw(owords, etext, feats, 1, 7200, 10000, 10200, 11200, 0, 0, 0, emon.Testport.TextBlob("seen"));
        XlOw(owords, etext, feats, 1, 11000, 10000, 14000, 11200, 0, 0, 0, emon.Testport.TextBlob("olden"));
        XlOw(owords, etext, feats, 1, 15000, 10000, 18000, 11200, 0, 0, 0, emon.Testport.TextBlob("clip"));
        emon.Testport.AssertEq(XlAlign(epages, words, owords, tlines, feats, etext, refs, cg, 1), 3, "seen, the hidden layer's word, and the OCR-only clip");
        emon.Testport.AssertEq(Player.CgGet(cg, 0, Player.CgfTcount()), 1, "seen is a visible word");
        emon.Testport.AssertEq(Player.CgGet(cg, 1, Player.CgfTcount()), 0, "the hidden word is not in the visible run");
        emon.Testport.AssertEq(Player.CgGet(cg, 1, Player.CgfHcount()), 1, "it is in the hidden one");
        emon.Testport.AssertEq(Player.CgGet(cg, 1, Player.CgfOcount()), 1, "with its OCR word");
        emon.Testport.AssertEq(Player.CgGet(cg, 1, Player.CgfSim()), 800, "older / olden, hidden against OCR");
        emon.Testport.AssertEq(Evidence.FeGet(feats, 4, Evidence.XoSimHidden()), 800, "the OCR word's column 25");
        emon.Testport.AssertEq(Evidence.FeGet(feats, 4, Evidence.XoSimText()), -1, "and not column 24");
        emon.Testport.AssertEq(Player.CgGet(cg, 2, Player.CgfFlags()), Player.PlgOcrOnly(), "the clipped word is no candidate: OCR-only");
        emon.Testport.AssertEq(Player.CgGet(cg, 2, Player.CgfTcount()), 0, "no text");
    }
