    }
    [Xunit.Fact]
    public static void TestPagesDoNotLeak() {
        emon.Port.Cells epages = emon.Port.NewCells();
        emon.Port.Cells words = emon.Port.NewCells();
        emon.Port.Cells owords = emon.Port.NewCells();
        emon.Port.Cells tlines = emon.Port.NewCells();
        emon.Port.Cells feats = emon.Port.NewCells();
        emon.Port.Cells etext = emon.Port.NewCells();
        emon.Port.Cells refs = emon.Port.NewCells();
        emon.Port.Cells cg = emon.Port.NewCells();
        Evidence.EpNew(epages, 1, 61200, 79200);
        Evidence.EpNew(epages, 2, 61200, 79200);
        XlTw(words, etext, feats, 1, 7200, 10000, 10200, 11200, 0, 0, 0, Model.SrText(), 0, emon.Testport.TextBlob("page"));
        XlTw(words, etext, feats, 2, 7200, 10000, 10200, 11200, 0, 0, 0, Model.SrText(), 0, emon.Testport.TextBlob("next"));
        XlOw(owords, etext, feats, 1, 7200, 10000, 10200, 11200, 0, 0, 0, emon.Testport.TextBlob("page"));
        XlOw(owords, etext, feats, 2, 7200, 10000, 10200, 11200, 0, 0, 0, emon.Testport.TextBlob("mext"));
        emon.Testport.AssertEq(XlAlign(epages, words, owords, tlines, feats, etext, refs, cg, 1), 1, "page 1: one group");
        emon.Testport.AssertEq(Player.CgGet(cg, 0, Player.CgfSim()), 1000, "page");
        emon.Testport.AssertEq(Player.CgGet(cg, 0, 0), 1, "on page 1");
        emon.Testport.AssertEq(XlAlign(epages, words, owords, tlines, feats, etext, refs, cg, 2), 1, "page 2: one group");
        emon.Testport.AssertEq(Player.CgGet(cg, 1, Player.CgfSim()), 750, "next / mext");
        emon.Testport.AssertEq(Player.CgGet(cg, 1, 0), 2, "on page 2");
        emon.Testport.AssertEq(XlAlign(epages, words, owords, tlines, feats, etext, refs, cg, 3), 0, "page 3: nothing");
        emon.Testport.AssertEq(Player.CgCount(cg), 2, "two rows");
        emon.Testport.AssertEq(Evidence.RfGet(refs, Player.CgGet(cg, 1, Player.CgfTfirst()), 1), 1, "page 2's text word is words row 1");
    }
    [Xunit.Fact]
    public static void TestALineTooLongForTheTableIsPairedGreedily() {
        emon.Port.Cells epages = emon.Port.NewCells();
        emon.Port.Cells words = emon.Port.NewCells();
        emon.Port.Cells owords = emon.Port.NewCells();
        emon.Port.Cells tlines = emon.Port.NewCells();
        emon.Port.Cells feats = emon.Port.NewCells();
        emon.Port.Cells etext = emon.Port.NewCells();
        emon.Port.Cells refs = emon.Port.NewCells();
        emon.Port.Cells cg = emon.Port.NewCells();
        int i = 0;
        Evidence.EpNew(epages, 1, 100000000, 79200);
        while (i < 1100) {
            XlTw(words, etext, feats, 1, 1000 + (i * 100), 10000, 1060 + (i * 100), 11200, 0, 0, 0, Model.SrText(), 0, emon.Testport.TextBlob("w"));
            XlOw(owords, etext, feats, 1, 1005 + (i * 100), 10000, 1065 + (i * 100), 11200, 0, 0, 0, emon.Testport.TextBlob("w"));
            i += 1;
        }
        emon.Testport.AssertEq(XlAlign(epages, words, owords, tlines, feats, etext, refs, cg, 1), 1100, "every word is a group");
        emon.Testport.AssertEq(Player.CgGet(cg, 1099, Player.CgfOcount()), 1, "the last has its OCR word");
        emon.Testport.AssertEq(XlRef(cg, refs, 1099, Player.CgfOfirst(), 0), 1099, "which is the last");
        emon.Testport.AssertEq(Player.CgGet(cg, 500, Player.CgfFlags()), 0, "paired");
    }
